import { Component } from '@angular/core';
import { GalleryThumbs } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';
import { NgOptimizedImage } from '@angular/common';

@Component({
  selector: 'app-demo',
  imports: [GalleryThumbs, GalleryModule, NgOptimizedImage],
  template: `
    <gallery [items]="items">
        <img
            *galleryItemDef="let item"
            galleryImage
            [src]="item.src"
            [alt]="item.alt" />
        <gallery-thumbs
            [position]="position"
            [gap]="gap"
            [initialIndex]="initialIndex"
            [thickness]="thickness"
            [itemSize]="itemSize"
            [itemsPerView]="itemsPerView"
            [snapAlign]="snapAlign"
            [forceSnap]="forceSnap"
            [scrollBehavior]="scrollBehavior"
            [scrollDuration]="scrollDuration"
            [disableMouseScroll]="disableMouseScroll"
            [disableScroll]="disableScroll"
            [detach]="detach"
            [loop]="loop"
            [floating]="floating">
            <button *galleryItemDef="let item" galleryThumbClick>
                <img galleryImage [src]="item.thumb" [alt]="item.alt + '_thumb'"/>
            </button>
        </gallery-thumbs>
    </gallery>`,
})
export class DemoComponent {
  position = 'bottom';
  itemSize = 120;
  thickness = 90;
  itemsPerView = 1;
  gap = 1;
  scrollBehavior = 'smooth';
  scrollDuration = 268;
  loop = false;
  detach = false;
  floating = false;
  snapAlign = 'center';
  forceSnap = false;
  disableScroll = false;
  disableMouseScroll = false;
}

