import { Component } from '@angular/core';
import { GalleryThumbs } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';
import { NgOptimizedImage } from '@angular/common';

@Component({
  selector: 'app-demo',
  imports: [GalleryThumbs, GalleryModule, NgOptimizedImage],
  template: `
    <gallery class="gallery-example" [items]="items">
        <div
            *galleryItemDef="let item; index as i"
            class="slide"
            [style.background]="item.src">
            Slide {{ i + 1 }}
        </div>
        <gallery-thumbs floating itemSize="6" thickness="6" gap="6">
            <button
                *galleryItemDef="let item; index as i"
                class="dot-thumb">
            </button>
        </gallery-thumbs>
    </gallery>`,
})
export class DemoComponent {}

