        </div>
        <gallery-thumbs position="start" itemSize="100">
            <button *galleryItemDef="let item; index as i"  galleryThumbClick>
                <div class="slide-thumb">{{ i + 1 }}</div>
            </button>
        </gallery-thumbs>
    </gallery>`,
})
export class DemoComponent {}

